&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;fgplg-0-0&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/div&gt;
